import {moods,styles,endings} from './music.js';
import {tracks,normalizeMix} from './mix.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export async function api(path,method='GET',data){const r=await fetch('/api'+path,{method,credentials:'same-origin',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let result;try{result=await r.json()}catch{throw Error('账户与双人房间需要完整服务器支持，当前部署未连接该服务。')}if(!r.ok)throw Error(result.error||'请求未完成');return result}
const options=obj=>Object.entries(obj).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('');
export class Social{
 constructor({root,onAccount,onProject,onView,onLocalStart,toast}){Object.assign(this,{root,onAccount,onProject,onView,onLocalStart,toast});this.localOnly=['localhost','127.0.0.1','[::1]'].includes(location.hostname);this.user=null;this.poll=null;this.invite='';this.room=null;this.inviteUrl='';this.createDialog();}
 async init(){try{const s=await api('/session');this.available=true;this.localOnly=!!s.localOnly;this.user=s.user;this.header();await this.onAccount(this.user)}catch{this.available=false;this.header()}window.addEventListener('hashchange',()=>this.route());this.route()}
 route(){if(this.localOnly)return;const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('invite'))this.showInvite(hash.get('invite'));else if(hash.has('room')&&this.user)this.openRoom(hash.get('room'))}
 header(){const node=document.querySelector('#account-actions');node.innerHTML=this.user?`<button class="account-name" id="account-hub">◉ ${esc(this.user.displayName)}</button><button class="account-logout" id="account-logout">退出</button>`:'<button id="login-button" class="login-button">登录</button><button id="register-button" class="register-button">注册</button>';if(this.localOnly){node.querySelector('#login-button')?.replaceChildren('本机登录');node.querySelector('#register-button')?.replaceChildren('创建本机账户');document.querySelector('[data-nav=rooms]').textContent='同机双人';document.querySelector('#share-site').textContent='分享方式'}node.querySelector('#login-button')?.addEventListener('click',()=>this.showAuth('login'));node.querySelector('#register-button')?.addEventListener('click',()=>this.showAuth('register'));node.querySelector('#account-hub')?.addEventListener('click',()=>this.hub());node.querySelector('#account-logout')?.addEventListener('click',async()=>{try{await api('/auth/logout','POST',{});this.user=null;this.stopPolling();this.header();await this.onAccount(null);this.toast('已退出登录')}catch(e){this.toast(e.message)}})}
 createDialog(){const dialog=document.createElement('dialog');dialog.id='auth-dialog';document.body.append(dialog);this.auth=dialog}
 showAuth(mode='login',after){this.afterAuth=after;this.auth.innerHTML=`<button class="close-dialog text-btn" aria-label="关闭账户窗口">关闭</button><div class="eyebrow">${this.localOnly?'YOUR MEMORY, ON THIS COMPUTER':'YOUR MEMORY, ANYWHERE'}</div><h2>${mode==='register'?'为回忆，留一个位置。':'欢迎回到你的旋律。'}</h2><p>${this.localOnly?'这是本机账户，账号与作品保存在此文件夹的数据库中，不会跨电脑同步。无需登录也能创作；同机双人可直接开始。':'登录后可跨设备收藏作品，也能与另一个人远程共创。'}</p><form id="auth-form"><label>账号<input name="username" autocomplete="username" required minlength="3" maxlength="32" placeholder="3–32 个字、字母或数字"></label>${mode==='register'?'<label>昵称<input name="displayName" autocomplete="nickname" maxlength="32" placeholder="希望怎样称呼你"></label>':''}<label>密码<input name="password" type="password" autocomplete="${mode==='register'?'new-password':'current-password'}" required minlength="10" maxlength="128" placeholder="至少 10 位"></label><p class="form-error" role="alert"></p><button class="primary" type="submit">${mode==='register'?'创建账号':'登录'}</button></form><button class="auth-switch text-btn">${mode==='register'?'已有账号，去登录':'还没有账号，去注册'}</button>`;this.auth.querySelector('.close-dialog').onclick=()=>this.auth.close();this.auth.querySelector('.auth-switch').onclick=()=>this.showAuth(mode==='register'?'login':'register',after);this.auth.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button');button.disabled=true;form.querySelector('.form-error').textContent='';try{const {user}=await api('/auth/'+mode,'POST',Object.fromEntries(new FormData(form)));this.available=true;this.user=user;this.header();await this.onAccount(user);this.auth.close();this.toast(mode==='register'?'账号已创建':'登录成功');if(after)after()}catch(error){form.querySelector('.form-error').textContent=error.message}finally{button.disabled=false}};if(!this.auth.open)this.auth.showModal()}
 stopPolling(){clearInterval(this.poll);this.poll=null}
 enter(){this.stopPolling();this.onView();window.scrollTo(0,0)}
 async hub(mode='couple'){if(this.localOnly){this.localHub(mode);return}this.enter();if(!this.user){this.root.innerHTML=`<section class="social-hub"><div class="eyebrow">TWO DEVICES, ONE MEMORY</div><h1>隔着屏幕，也能写同一首回忆。</h1><p>创建一个邀请房间，把链接发给 TA。各自填写自己的视角，最后让两份心情在音乐里相遇。</p><button class="primary" id="hub-login">登录并开始共创</button><p class="hint">单人创作仍可免登录使用。</p></section>`;document.querySelector('#hub-login').onclick=()=>this.showAuth('login',()=>this.hub(mode));return}
 this.root.innerHTML=`<section class="social-hub"><div class="eyebrow">OUR LITTLE RECORDING ROOM</div><h1>两个人，两段记忆，一个回声。</h1><div class="room-create"><h2>创建共同回忆</h2><form id="room-create-form"><label>回忆标题<input name="title" maxlength="40" required placeholder="例如：那次一起去看海"></label><div class="social-form-grid"><label>共创模式<select name="mode"><option value="couple" ${mode==='couple'?'selected':''}>情侣</option><option value="friends" ${mode==='friends'?'selected':''}>朋友</option></select></label><label>共同音乐风格<select name="style">${options(styles)}</select></label><label>共同落幕方式<select name="ending">${options(endings)}</select></label></div><button class="primary">创建邀请房间</button><p class="form-error" role="alert"></p></form></div><div id="room-list"><p class="hint">正在读取你的房间…</p></div></section>`;
 document.querySelector('#room-create-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;try{const result=await api('/rooms','POST',Object.fromEntries(new FormData(f)));this.inviteUrl=location.origin+'/#invite='+encodeURIComponent(result.inviteToken);this.renderRoom(result.room)}catch(error){f.querySelector('.form-error').textContent=error.message}finally{b.disabled=false}};
 try{const {rooms}=await api('/rooms');const list=document.querySelector('#room-list');if(!list)return;list.innerHTML='<h2>我的共创房间</h2>'+ (rooms.length?rooms.map(r=>`<button class="room-list-item" data-room="${esc(r.id)}"><span>${esc(r.settings.title)}</span><small>${r.ready?'双方已提交，可生成音乐':r.guestName?'等待回忆填写':'等待另一位加入'}</small></button>`).join(''):'<p class="hint">还没有房间，邀请一个人一起开始吧。</p>');list.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>this.openRoom(b.dataset.room))}catch(e){const list=document.querySelector('#room-list');if(list)list.textContent=e.message}}
 localHub(mode='couple'){this.enter();this.root.innerHTML=`<section class="social-hub"><div class="eyebrow">SIDE BY SIDE, ONE MEMORY</div><h1>坐在一起，把回忆写成一首歌。</h1><p>选一种关系，在同一台电脑上分别写下故事和心情。两个人的主题，会在最后相遇。</p><div class="hero-actions"><button class="primary" id="local-couple">♡ 情侣回忆</button><button class="secondary" id="local-friends">♬ 朋友回忆</button></div><p class="hint">Windows 本地版无需登录即可共创。想发给另一台电脑，可以在完成后下载音频或备份作品；本地地址不提供远程访问。</p></section>`;document.querySelector('#local-couple').onclick=()=>this.onLocalStart('couple');document.querySelector('#local-friends').onclick=()=>this.onLocalStart('friends')}
 showInvite(token){this.enter();this.invite=token;this.root.innerHTML=`<section class="social-hub invitation"><div class="eyebrow">A MEMORY IS WAITING FOR YOU</div><div class="invite-orbits">♡<span>♪</span><span>♫</span></div><h1>有人想和你，留住同一段时光。</h1><p>接受邀请后，各自填写那天的故事。提交的回答会向房间内另一位参与者展示。</p><button class="primary" id="accept-invite">${this.user?'接受邀请':'登录并接受邀请'}</button><p class="form-error" id="invite-error" role="alert"></p></section>`;document.querySelector('#accept-invite').onclick=()=>{const join=async()=>{try{const {room}=await api('/rooms/join','POST',{token});history.replaceState(null,'',location.pathname+'#room='+room.id);this.inviteUrl='';this.renderRoom(room)}catch(e){document.querySelector('#invite-error').textContent=e.message}};if(this.user)join();else this.showAuth('login',join)}}
 async openRoom(id){if(!this.user){this.showAuth('login',()=>this.openRoom(id));return}try{const {room}=await api('/rooms/'+encodeURIComponent(id));this.inviteUrl='';this.renderRoom(room)}catch(e){this.toast(e.message)}}
 status(room){return `<div class="room-person"><span>◉ ${esc(room.hostName)}</span><b>${room.hostAnswer?'已提交回忆':'正在酝酿'}</b></div><div class="room-person"><span>◉ ${esc(room.guestName||'等待 TA 加入')}</span><b>${room.guestAnswer?'已提交回忆':room.guestName?'正在酝酿':'邀请尚未接受'}</b></div>`}
 renderRoom(room){this.enter();this.room=room;history.replaceState(null,'',location.pathname+'#room='+room.id);const own=room.role==='host'?room.hostAnswer:room.guestAnswer,other=room.role==='host'?room.guestAnswer:room.hostAnswer;this.root.innerHTML=`<section class="social-hub room-view"><button id="back-rooms" class="text-btn">返回我的房间</button><div class="eyebrow">OUR SHARED MEMORY</div><h1>${esc(room.settings.title)}</h1><p>${esc(styles[room.settings.style])} · ${esc(endings[room.settings.ending])} · 房间有效期 30 天</p><div class="room-status" id="room-status">${this.status(room)}</div>${room.role==='host'?`<div class="room-invite"><label>发给另一台设备的邀请链接<input id="room-invite-url" readonly value="${esc(this.inviteUrl)}" placeholder="点击生成邀请链接"></label><button class="secondary" id="make-invite">${this.inviteUrl?'复制邀请链接':'重新生成邀请链接'}</button><p class="hint">重新生成后，之前尚未使用的邀请将失效。房间最多两人。</p></div>`:''}<form id="room-answer-form" class="room-answer"><h2>写下属于你的那个视角</h2><label>你记得什么？<textarea name="story" maxlength="1200" required placeholder="同一天，在你的记忆里是什么样子？">${esc(own?.story||'')}</textarea></label><label>你的心情<select name="mood">${Object.entries(moods).map(([k,v])=>`<option value="${k}" ${own?.mood===k?'selected':''}>${v}</option>`).join('')}</select></label><label>想带进共同旋律的声音</label><div class="checks">${Object.entries(tracks).map(([k,v])=>`<label class="check"><input type="checkbox" name="${k}" ${own?own.instruments[k]?'checked':'':['piano','harmony'].includes(k)?'checked':''}>${v}</label>`).join('')}</div><label class="share-consent"><input type="checkbox" name="consent" required>我同意提交后将这份回答展示给房间内的另一位参与者。</label><button class="primary">${own?'更新我的回忆':'提交我的回忆'}</button><p class="form-error" role="alert"></p></form><div class="partner-answer"><h2>TA 记得的瞬间</h2><p id="partner-story">${esc(other?.story||'等 TA 提交后，这里会出现另一份回忆。')}</p></div><button class="primary shared-generate" id="generate-shared" ${room.ready?'':'disabled'}>♫ 生成我们的共同旋律</button><p id="room-sync-status" class="hint">房间状态自动同步；共同音乐生成后，各自的编曲调整另存为个人版本。</p></section>`;
 document.querySelector('#back-rooms').onclick=()=>this.hub();document.querySelector('#make-invite')?.addEventListener('click',async()=>{try{if(!this.inviteUrl){const r=await api('/rooms/'+room.id+'/invite','POST',{});this.inviteUrl=location.origin+'/#invite='+encodeURIComponent(r.inviteToken);document.querySelector('#room-invite-url').value=this.inviteUrl;document.querySelector('#make-invite').textContent='复制邀请链接'}await navigator.clipboard.writeText(this.inviteUrl);this.toast('邀请链接已复制')}catch{document.querySelector('#room-invite-url').select();this.toast('请复制选中的邀请链接')}});
 document.querySelector('#room-answer-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button'),d=new FormData(f);b.disabled=true;try{const {room:r}=await api('/rooms/'+room.id+'/answer','PUT',{story:d.get('story'),mood:d.get('mood'),shareConsent:d.has('consent'),instruments:Object.fromEntries(Object.keys(tracks).map(k=>[k,d.has(k)]))});this.renderRoom(r);this.toast('你的回忆已提交，对方设备会自动收到')}catch(error){f.querySelector('.form-error').textContent=error.message}finally{b.disabled=false}};
 document.querySelector('#generate-shared').onclick=async()=>{if(!this.room.ready)return;const button=document.querySelector('#generate-shared');button.disabled=true;button.textContent='正在谱写共同旋律…';this.stopPolling();const r=this.room,a=r.hostAnswer,b=r.guestAnswer;await this.onProject({id:r.id,title:r.settings.title,story:a.story,story2:b.story,name1:r.hostName,name2:r.guestName,mode:r.settings.mode,mood:a.mood,mood2:b.mood,style:r.settings.style,ending:r.settings.ending,memoryColor:r.settings.memoryColor,tempo:null,mix:normalizeMix(),variation:0,created:new Date(r.expires-30*86400000).toISOString(),instruments:Object.fromEntries(Object.keys(tracks).map(k=>[k,a.instruments[k]||b.instruments[k]]))});if(button.isConnected){button.disabled=false;button.textContent='♫ 生成我们的共同旋律'}};
 let fetching=false;this.poll=setInterval(async()=>{if(fetching||document.hidden)return;fetching=true;try{const {room:r}=await api('/rooms/'+room.id);if(this.room?.id!==room.id)return;if(!document.querySelector('#room-status')){this.stopPolling();return}this.room=r;document.querySelector('#room-status').innerHTML=this.status(r);document.querySelector('#generate-shared').disabled=!r.ready;document.querySelector('#partner-story').textContent=(r.role==='host'?r.guestAnswer:r.hostAnswer)?.story||'等 TA 提交后，这里会出现另一份回忆。';document.querySelector('#room-sync-status').textContent=r.ready?'双方已完成，现在可以生成同一份共同旋律。':'房间状态自动同步，等待另一份回忆…'}catch{const el=document.querySelector('#room-sync-status');if(el)el.textContent='连接暂时中断，正在尝试重新同步…'}finally{fetching=false}},2500)
 }
}
